const fs = require('fs');
const path = require('path');

function walkDir(dir, callback) {
  fs.readdirSync(dir).forEach(file => {
    const filePath = path.join(dir, file);
    if (fs.statSync(filePath).isDirectory()) {
      walkDir(filePath, callback);
    } else if (filePath.endsWith('route.ts')) {
      callback(filePath);
    }
  });
}

function fixApiRoute(filePath) {
  let content = fs.readFileSync(filePath, 'utf8');
  let modified = false;

  // Fix pattern: { params }: { params: { ... } }  =>  { params }
  // This handles both empty and populated param patterns
  const patterns = [
    // Pattern 1: { params }: { params: { [key: string]: string; } }
    /export (async )?((GET|POST|PUT|DELETE|PATCH|HEAD)\s*=\s*async\s*\(\s*request:\s*NextRequest,\s*{\s*params\s*}\s*:\s*{\s*params\s*:\s*{\s*\[key:\s*string\]\s*:\s*string\s*;\s*}\s*;\s*}\s*\))/g,
    // Pattern 2: { params }: { params: { id: string; } } etc
    /export (async )?((GET|POST|PUT|DELETE|PATCH|HEAD)\s*=\s*async\s*\(\s*request:\s*NextRequest,\s*{\s*params\s*}\s*:\s*{\s*params\s*:\s*{\s*[^}]+}\s*}\s*\))/g,
  ];

  // More targeted approach: replace the old pattern with the new one
  if (content.includes('{ params }: { params:')) {
    content = content.replace(
      /(\s*(?:export\s+)?(?:async\s+)?(?:const\s+)?(?:function\s+)?[A-Z]+\s*=\s*async\s*\(\s*request:\s*NextRequest,\s*)\{\s*params\s*\}\s*:\s*\{\s*params\s*:\s*\{\s*([^}]*)\}\s*;?\s*\}/g,
      '$1{ params }'
    );
    modified = true;
  }

  if (modified) {
    fs.writeFileSync(filePath, content, 'utf8');
    console.log(`Fixed: ${filePath}`);
  }
}

