  50 /**
  51  * Calculate cosine similarity between two vectors
  52  */
  53 function cosineSimilarity(a: number[], b: number[]): number {
  54   if (a.length !== b.length) {
  55     throw new Error('Vectors must have the same length');
  56   }
  57 
  58   let dotProduct = 0;
  59   let normA = 0;
  60   let normB = 0;
  61 
  62   for (let i = 0; i < a.length; i++) {
  63     dotProduct += a[i] * b[i];
  64     normA += a[i] * a[i];
  65     normB += b[i] * b[i];
  66   }
  67 
  68   const denominator = Math.sqrt(normA) * Math.sqrt(normB);
  69   return denominator === 0 ? 0 : dotProduct / denominator;
  70 }
