   3 /**
   4  * @fileOverview An AI agent for improving a full report provided in Markdown.
   5  */
   6 
   7 import { ai } from '@/ai/genkit';
   8 import { ImproveMarkdownInputSchema, ImproveMarkdownOutputSchema, type ImproveMarkdownInput, type ImproveMarkdownOutput } from '@/ai/schemas';
   9 import { validateJsonOutput, getJsonPromptInstructions, RECOMMENDED_TEMPERATURES } from '@/ai/utils/json-output-validator';
  10 
  11 const improveMarkdownPrompt = ai.definePrompt({
  12   name: 'improveReportMarkdownPrompt',
  13   input: { schema: ImproveMarkdownInputSchema },
  14   output: { schema: ImproveMarkdownOutputSchema },
  15   model: 'ollama/phi3:mini',
  16   config: {
  17     responseSchema: ImproveMarkdownOutputSchema,
  18     temperature: RECOMMENDED_TEMPERATURES.PRECISE,
  19   },
  20   prompt: `You are an expert technical editor and document formatter. A user has provided a full report in Markdown format and a set of instructions for how to improve it.
  21 
  22 ${getJsonPromptInstructions(`{
  23   "improvedText": "Complete improved markdown document with all enhancements applied"
  24 }`)}
  25 
  26 Your tasks are to:
  27 1.  **Analyze the Instructions**: Carefully read the user's prompt to understand their goals (e.g., make it more formal, add a summary, remove specific sections, check for consistency).
  28 2.  **Restructure and Reformat**: Apply the user's instructions to the provided Markdown content. This includes organizing headings, ensuring consistent formatting for lists and tables, and improving the overall flow.
  29 3.  **Enhance Writing Quality**: Improve the clarity, conciseness, and professionalism of the writing. Correct grammatical errors and awkward phrasing.
  30 4.  **Fill Gaps (If Requested)**: If the user asks to add information and provides context, intelligently integrate it. Do not invent new facts.
  31 5.  **Return Clean Markdown**: Your final output must be only the complete, improved Markdown document inside the correct JSON structure.
  32 
  33 ---
  34 **User Instructions:**
  35 {{{prompt}}}
  36 ---
  37 **Original Markdown Document:**
  38 {{{text}}}
  39 ---
  40 
  41 **JSON Output:**`,
  42 });
  43 
  44 const improveReportMarkdownFlow = ai.defineFlow({
  45   name: 'improveReportMarkdownFlow',
  46   inputSchema: ImproveMarkdownInputSchema,
  47   outputSchema: ImproveMarkdownOutputSchema
  48 }, async (input) => {
  49   try {
  50     const { output } = await improveMarkdownPrompt(input);
  51     
  52     if (!output) {
  53       throw new Error('No output received from the model.');
  54     }
  55 
  56     const validation = validateJsonOutput({
  57       schema: ImproveMarkdownOutputSchema,
  58       output,
  59       flowName: 'improveReportMarkdownFlow',
  60       attemptRecovery: true,
  61       enableLogging: true,
  62       fallbackFn: (rawOutput) => {
  63         if (typeof rawOutput === 'string') {
  64           return { improvedText: rawOutput };
  65         }
  66         return null;
  67       },
  68     });
  69 
  70     if (!validation.success) {
  71       throw new Error(validation.error || 'Failed to validate output');
  72     }
  73 
  74     return validation.data!;
  75   } catch (error) {
  76     console.error('Error in improveReportMarkdownFlow:', error);
  77     throw new Error(`Markdown improvement failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
  78   }
  79 });
  80 
  81 export async function improveReportMarkdown(input: ImproveMarkdownInput): Promise<ImproveMarkdownOutput> {
  82   const validation = ImproveMarkdownInputSchema.safeParse(input);
  83   if (!validation.success) {
  84     throw new Error(`Invalid input for improveReportMarkdown: ${validation.error.message}`);
  85   }
  86   return improveReportMarkdownFlow(validation.data);
  87 }
  88 
