  14 function getStatusInfo(status: ClaimStatus) {
  15   switch (status) {
  16     case 'Verified':
  17       return { icon: CheckCircle, color: 'text-green-500', badgeVariant: 'default' as const };
  18     case 'Inconclusive':
  19       return { icon: HelpCircle, color: 'text-yellow-500', badgeVariant: 'secondary' as const };
  20     case 'False':
  21       return { icon: XCircle, color: 'text-destructive', badgeVariant: 'destructive' as const };
  22   }
  23 };
  24 
  25 function getScoreColor(score: number) {
  26   if (score < 50) return 'text-destructive';
  27   if (score < 80) return 'text-yellow-500';
  28   return 'text-green-500';
  29 }
  30 
  31 export function FactCheckerTool() {
  32   const { t } = useLocalization();
  33   const {
  34     form,
  35     mutation,
  36     isUploading,
  37     getRootProps,
