  45     <Card>
  46       <CardHeader>
  47         <CardTitle>{t('writingTools.factChecker.cardTitle')}</CardTitle>
  48         <CardDescription>{t('writingTools.factChecker.cardDescription')}</CardDescription>
  49       </CardHeader>
  50       <CardContent className="space-y-6">
  51         <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
  52           <Tabs defaultValue="paste">
  53             <TabsList className="grid w-full grid-cols-2">
  54               <TabsTrigger value="paste">{t('writingTools.factChecker.pasteTab')}</TabsTrigger>
  55               <TabsTrigger value="upload">{t('writingTools.factChecker.uploadTab')}</TabsTrigger>
  56             </TabsList>
  57             <TabsContent value="paste" className="pt-4">
  58               <Textarea
  59                 {...form.register('text')}
  60                 rows={12}
  61                 placeholder={t('writingTools.factChecker.placeholder')}
  62                 className="resize-none"
  63                 disabled={mutation.isPending || isUploading}
  64               />
  65             </TabsContent>
  66             <TabsContent value="upload" className="pt-4">
  67               <div {...getRootProps()} className={`border-2 border-dashed rounded-lg p-12 text-center cursor-pointer ${isDragActive ? 'border-primary' : ''}`}>
  68                 <input {...getInputProps()} />
  69                 <UploadCloud className="mx-auto h-12 w-12 text-muted-foreground" />
  70                 {isUploading ? (
  71                   <p className="mt-2 text-sm text-muted-foreground">{t('writingTools.factChecker.processingFile')}</p>
  72                 ) : (
  73                   <p className="mt-2 text-sm text-muted-foreground">{t('writingTools.factChecker.dropzoneHint')}</p>
  74                 )}
  75                 <p className="text-xs text-muted-foreground">{t('writingTools.factChecker.supportedFiles')}</p>
  76               </div>
  77             </TabsContent>
  78           </Tabs>
  79           {form.formState.errors.text && <p className="text-sm text-destructive">{form.formState.errors.text.message}</p>}
  80 
  81           <Button type="submit" disabled={mutation.isPending || isUploading} className="w-full">
  82             {mutation.isPending || isUploading ? <Loader2 className="me-2 h-4 w-4 animate-spin" /> : <Sparkles className="me-2 h-4 w-4" />}
  83             {t('writingTools.factChecker.checkButton')}
  84           </Button>
  85         </form>
  86 
  87         {mutation.isPending && (
  88           <div className="pt-6 border-t">
  89             <div className="flex justify-center items-center text-sm text-muted-foreground mb-2">
  90               <Loader2 className="me-2 h-4 w-4 animate-spin" />
  91               {t('writingTools.factChecker.analyzing')}
  92             </div>
  93           </div>
  94         )}
  95 
  96         {results && (
  97           <div className="space-y-4 pt-6 border-t">
  98             <h3 className="font-semibold text-lg">{t('writingTools.factChecker.reportTitle')}</h3>
  99             <Card className="bg-muted/50">
 100               <CardContent className="p-4 flex items-center justify-center text-center gap-4">
 101                 <div className={`text-6xl font-bold ${getScoreColor(results.originalityScore)}`}>
 102                   {results.originalityScore}%
 103                 </div>
 104                 <div>
 105                   <p className="font-semibold">{t('writingTools.factChecker.originalityScore')}</p>
 106                   <p className="text-xs text-muted-foreground">{t('writingTools.factChecker.originalityScoreDesc')}</p>
 107                 </div>
 108               </CardContent>
 109             </Card>
 110             <div className="space-y-2">
 111               <h4 className="font-semibold">{t('writingTools.factChecker.matchesTitle')}</h4>
 112               <p className="text-sm text-muted-foreground">
 113                 {t('writingTools.factChecker.matchesDescription')}
 114               </p>
 115               {results.claims.length > 0 ? (
 116                 <div className="space-y-4">
 117                   {results.claims.map((claim: FactCheckOutput['claims'][0], index: number) => {
 118                     const { icon: Icon, color, badgeVariant } = getStatusInfo(claim.status);
 119                     return (
