 129                         <p className="text-xs text-muted-foreground">{t('writingTools.factChecker.sourceLabel')}
 130                           <Link href={`https://${claim.source}`} target="_blank" className="hover:underline text-primary">
 131                             {claim.source} <ExternalLink className="inline h-3 w-3" />
 132                           </Link>
 133                         </p>
 134                       </div>
 135                     )
 136                   })}
 137                 </div>
 138               ) : (
 139                 <div className="text-center text-muted-foreground py-8 border-dashed border-2 rounded-lg">
 140                   <p>{t('writingTools.factChecker.noClaims')}</p>
