  26         if (!project?.sections) return {};
  27         return project.sections.reduce((acc, section) => {
  28             acc[section.id] = section.content || '';
  29             return acc;
  30         }, {} as Record<string, string>);
  31     }, [project?.sections]);
  32 
  33 
  34     const handleContextChange = useCallback((
  35         sectionId: string,
  36         type: 'sections' | 'externalContext',
  37         subKey: string,
  38         value: ExternalContextType | false
  39     ) => {
  40         updateProject(p => p.updateSection(sectionId, (sec) => {
  41             const newContext = { ...sec.context };
  42             const newDict = { ...(newContext[type] || {}) };
  43             
  44             if (value === false) {
  45                 delete newDict[subKey];
  46             } else {
  47                 newDict[subKey] = value;
  48             }
  49             
  50             newContext[type] = newDict;
  51             return sec.with({ context: newContext });
  52         }));
  53     }, [updateProject]);
